mapper.select:
select
(select  count(*) from Sys_FileAnnex fa where fa.File_Relation_Id=f.File_Relation_Id
 and fa.upload_status=1 and fa.File_Location=0) as fileCount,
(select count(*) from Project_Cp_Work_Comment cpwc where cpwc.Cpwr_Id=cpwr.Cpwr_Id) as commentCount,



from  Project_Cp_Work_Record cpwr
left join  Project_Cp_Dtl cpd on cpd.Cpd_Id=cpwr.Cpd_Id
left join  Project_Cp cp on cp.Cp_Id=cpd.Cp_Id
left join  Pre_Project pro on pro.P_ID=cp.P_ID
left join Sys_File f on f.fileid=cpwr.Cpwr_Id


    
        and cpwr.Te_Id = #{params.teId}
    
    
        and  cpwr.Cpd_Id=#{params.cpdId}
    
    
        and  cpwr.Cpwr_Home_Push=#{params.cpwrHomePush}
    
    
        and cp.P_ID=#{params.pId}
    
    
        and (cpwr.Cpwr_Home_Push=true or cpwr.Cpwr_Create_Uid=#{params.authId})
    
    
        
            
                and likePname(#{params.pName},cp.P_ID)=true
            
            
                and pro.P_Name like concat('%',#{params.pName},'%')
            
        
    
    
        and  cpd.Cpd_Name like concat('%',#{params.cpdName},'%')
    
    
        and  cpwr.Cpwr_Create_Uname like concat('%',#{params.cpwrCreateUname},'%')
    
    
        and  cpwr.Cpwr_Remark like concat('%',#{params.cpwrRemark},'%')
    
    
        and cpwr.Cpwr_Create_Time>=#{params.cpwrCreateTimeStart}
    
    
        and cpwr.Cpwr_Create_Time <=#{params.cpwrCreateTimeEnd}
    
    
        and cpwr.Cpwr_Filling_Time>=#{params.cfTimeStart}
    
    
        and cpwr.Cpwr_Filling_Time <=#{params.cfTimeEnd}
    
    
        and cpd.Cpd_Create_Time>=#{params.cpdCreateTimeStart}
    
    
        and cpd.Cpd_Create_Time <=#{params.cpdCreateTimeEnd}
    


    
        order by cpwr.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by cpwr.Cpwr_Create_Time desc
